INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5832323, 847663, 47541, '<td valign="top">Hi from the Critique Club<br/> <br/>First impressions of the shot are that it meets challenge and is composed well.<br/> <br/>The plain white background helps with the interpretation of a face but it also makes the shot quite sterile. I think this is the main reason the score was under 5.5. On a technical level there isn''t much to say about the shot other than that the lighting could be improved on the camera body a little. Other than that it''s fine.<br/> <br/>For DPC it''s just lacking a bit of "wow" that would get it up to a 6.</td>', 'Hi from the Critique Club First impressions of the shot are that it meets challenge and is composed well. The plain white background helps with the interpretation of a face but it also makes the shot quite sterile. I think this is the main reason the score was under 5.5. On a technical level there isn''t much to say about the shot other than that the lighting could be improved on the camera body a little. Other than that it''s fine. For DPC it''s just lacking a bit of "wow" that would get it up to a 6.', '2010-01-25 13:11:25.000000', NULL, 0),
(5832337, 847593, 47541, '<td valign="top">Hi from the Critique Club<br/> <br/>When this came up I thought why does someone who is in the top 5 want a critique? I guess the comments since voting have been of the "good one" style rather than a critique so here goes...<br/> <br/>First impressions are that it meets challenge well and looks like it was a find, rather than contrived. The cropping/composition gives a feeling of being tilted at first but then we glimpse the other boards at the side and then it seems to take on a lifelike feel - like one in a crowd.<br/> <br/>The tones are nice, the nose adding a much needed element of colour to the otherwise bland wood. DOF seems to be a little shallow, the mouth is in focus but the eyes seem to be getting a little fuzzy.<br/> <br/>Overall its a nice shot with a good whimsical face showing.</td>', 'Hi from the Critique Club When this came up I thought why does someone who is in the top 5 want a critique? I guess the comments since voting have been of the "good one" style rather than a critique so here goes... First impressions are that it meets challenge well and looks like it was a find, rather than contrived. The cropping/composition gives a feeling of being tilted at first but then we glimpse the other boards at the side and then it seems to take on a lifelike feel - like one in a crowd. The tones are nice, the nose adding a much needed element of colour to the otherwise bland wood. DOF seems to be a little shallow, the mouth is in focus but the eyes seem to be getting a little fuzzy. Overall its a nice shot with a good whimsical face showing.', '2010-01-25 13:17:47.000000', NULL, 0),
(5832339, 847303, 98339, '<td valign="top">great picture...so glad you got the ribbon...this is the 2nd time that I''ve missed it by .006? or less...*double sigh*...need to do something to kick it up a notch...but given my picture I don''t know how I could have "kicked that up"...</td>', 'great picture...so glad you got the ribbon...this is the 2nd time that I''ve missed it by .006? or less...*double sigh*...need to do something to kick it up a notch...but given my picture I don''t know how I could have "kicked that up"...', '2010-01-25 13:19:41.000000', NULL, 0),
(5832345, 847660, 98339, '<td valign="top">what a super job Brent!!!  you''ve got to be proud...extremely well done</td>', 'what a super job Brent!!!  you''ve got to be proud...extremely well done', '2010-01-25 13:20:46.000000', NULL, 0),
(5832349, 847595, 98339, '<td valign="top">great picture David...one of my top picks...should have been higher</td>', 'great picture David...one of my top picks...should have been higher', '2010-01-25 13:21:40.000000', NULL, 0),
(5832354, 847593, 67152, '<td valign="top">Well done to find this!  A great smiling face.</td>', 'Well done to find this!  A great smiling face.', '2010-01-25 13:25:59.000000', NULL, 0),
(5832406, 847573, 112107, '<td valign="top">Damn! This picture just pops at you when viewing in full screen! When I saw the thumbnail, I wasn''t expecting much but it has got great contrast!<br/>The way the warm and soft tones battle with the sharp focus gives it so much *PUNCH!* <br/>And the soft vignetting really pulls you in.<br/> <br/>Great technically and artisticaly.<br/>Very underrated!<br/>I''d give it an 8/9 had I voted!</td>', 'Damn! This picture just pops at you when viewing in full screen! When I saw the thumbnail, I wasn''t expecting much but it has got great contrast!The way the warm and soft tones battle with the sharp focus gives it so much *PUNCH!* And the soft vignetting really pulls you in. Great technically and artisticaly.Very underrated!I''d give it an 8/9 had I voted!', '2010-01-25 13:45:17.000000', NULL, 0),
